"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["27457"],{41848(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.hash_colisao","status":409,"titulo":"Colis\xe3o de hash de regra ativa"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.hash_colisao","requisitos":[],"oQueAconteceu":["A grava\xe7\xe3o violou a unicidade do hash do conte\xfado can\xf4nico entre as regras legais **ativas**: o banco\\nde dados j\xe1 tem uma regra ativa com o mesmo hash. O hash \xe9 calculado sobre o tipo de processo, a\\ncategoria, o c\xf3digo de regra, o predicado, a base legal, a portaria interna e a vig\xeancia. Nada \xe9\\ngravado.","O c\xf3digo de regra faz parte desse conte\xfado. Por isso uma regra que repete outra ativa \xe9, em\\ncondi\xe7\xf5es normais, recusada antes, com\\n[`regra_codigo_duplicada`](/erros/uniplus.selecao.obrigatoriedade_legal.regra_codigo_duplicada). O\\ncen\xe1rio prov\xe1vel deste erro \xe9 a escrita concorrente de conte\xfado id\xeantico: as duas escritas passam\\npela confer\xeancia pr\xe9via, e o banco barra a segunda. Como o conte\xfado repete tamb\xe9m o c\xf3digo de regra,\\no banco pode apontar qualquer uma das duas unicidades, e a resposta sai com o c\xf3digo\\ncorrespondente. A resposta tem status 409, e n\xe3o \xe9 erro interno do servidor. Ela n\xe3o indica qual\\nescrita concorrente venceu nem se o conte\xfado da regra existente \xe9 de fato o mesmo.","A descri\xe7\xe3o da regra e o endere\xe7o do ato normativo n\xe3o entram no hash: mud\xe1-los n\xe3o distingue uma\\nregra da outra."],"comoResolver":["Consulte a listagem de obrigatoriedades legais com `vigentes=false` e confira o conte\xfado da regra\\nexistente com o que voc\xea enviou antes de concluir que s\xe3o equivalentes. Sem esse par\xe2metro a listagem\\ntraz s\xf3 as regras vigentes na data de hoje, e uma regra ativa que ainda n\xe3o come\xe7ou a valer, ou que j\xe1\\nencerrou a vig\xeancia, continua sujeita \xe0 unicidade e n\xe3o apareceria. Se for a regra que voc\xea queria, n\xe3o h\xe1 mais o que\\nfazer. Se a sua regra deve ser outra, altere o conte\xfado que a distingue, ou atualize a regra\\nexistente."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);